  if(!baseline){await page.waitForTimeout(900);if(simulation||process.env.WENJIAN_TEST_DESKTOP_PLATFORM==='mac')await app.evaluate(()=>global.__testCheckpoint());const storeFile=path.join(data,'notebook.json'),original=fs.readFileSync(storeFile),changed=JSON.parse(original);changed.data.libraryBooks[0].storedFile='scan.pdf';fs.writeFileSync(storeFile,JSON.stringify(changed));try{const length=await page.evaluate(()=>fetch('/api/library/file/large',{headers:{Range:'bytes=0-15'}}).then(async response=>{await response.arrayBuffer();return response.headers.get('content-range');}));assert.equal(length,'bytes 0-15/'+fs.statSync(files.scan).size);report.checks.push('PDF file index invalidates when the notebook changes externally');}finally{fs.writeFileSync(storeFile,original);}}

