    await page.getByRole('button').filter({has:page.getByText('Scanned PDF Fixture',{exact:true})}).first().click();await page.waitForFunction(()=>document.querySelector('.pdf-stage')?.dataset.pdfQuality==='full'&&document.querySelector('.pdf-stage')?.getAttribute('aria-busy')==='false');
